def preflight():
    required=[TEMPLATES/"5sw-wk6-student.html",TEMPLATES/"5sw-wk6-teacher.html",*(ROOT/"docs/resources/worksheets"/name for name in WORKSHEET_NAMES.values()),*(ASSETS/name for name in VISUAL_NAMES.values())]
    missing=[str(path.relative_to(ROOT)) for path in required if not path.is_file()]
    if missing: raise FileNotFoundError(f"5SW Wk6 preflight missing required files: {missing}")

async def canvas_preflight(client):
    modules=await common.paged(client,f"/courses/{COURSE_ID}/modules")
    accepted={MODULE_NAME,*MODULE_ALIASES}; module_matches=[entry for entry in modules if entry.get("name") in accepted]
    if len(module_matches)>1: raise RuntimeError(f"Duplicate Week 6 modules: {[entry['id'] for entry in module_matches]}")
    assignments=await common.paged(client,f"/courses/{COURSE_ID}/assignments")
    for title in TITLES.values():
        aliases={title,*FORMATIVE_ALIASES} if title==TITLES[5] else {title}
        matches=[entry for entry in assignments if entry.get("name") in aliases]
        if title==TITLES[5] and len(matches)!=1: raise RuntimeError(f"Expected exactly one Week 6 formative assignment; found {[entry['id'] for entry in matches]}")
        if title!=TITLES[5] and len(matches)>1: raise RuntimeError(f"Duplicate assignments named {title!r}: {[entry['id'] for entry in matches]}")
    formative=next(entry for entry in assignments if entry.get("name") in {TITLES[5],*FORMATIVE_ALIASES})
    groups=await common.paged(client,f"/courses/{COURSE_ID}/assignment_groups")
    group=next((entry for entry in groups if entry.get("id")==formative.get("assignment_group_id")),None)
    if not group or group.get("name") in {"Minor Assessments (40%)","Major Assessments (60%)"} or formative.get("published") or float(formative.get("points_possible") or 0)!=0 or formative.get("grading_type")!="percent" or formative.get("omit_from_final_grade") is not True:
        raise RuntimeError("Week 6 formative assignment failed prewrite grade-neutral/unpublished checks")
    quizzes=await common.paged(client,f"/courses/{COURSE_ID}/quizzes")
    matches=[entry for entry in quizzes if entry.get("title")==TITLES[4]]
    if len(matches)>1: raise RuntimeError(f"Duplicate quizzes named {TITLES[4]!r}: {[entry['id'] for entry in matches]}")
    return formative

