async def upload_locked(client,path,folder_path):
    uploaded=await common.upload(client,path,folder_path); record=await common.api(client,"GET",f"/files/{uploaded['id']}")
    if not record.get("locked"): record=await common.api(client,"PUT",f"/files/{uploaded['id']}",data={"locked":"true"})
    if not record.get("locked"): raise RuntimeError(f"Canvas did not lock {path.name!r}")
    return record

async def lock_folder_files(client,folder):
    current=await common.api(client,"GET",f"/folders/{folder['id']}")
    if not current.get("locked"): current=await common.api(client,"PUT",f"/folders/{folder['id']}",data={"locked":"true"})
    if not current.get("locked"): raise RuntimeError(f"Canvas did not lock folder {folder['id']}")
    for record in await common.paged(client,f"/folders/{folder['id']}/files"):
        if not record.get("locked"): await common.api(client,"PUT",f"/files/{record['id']}",data={"locked":"true"})
    final=await common.paged(client,f"/folders/{folder['id']}/files")
    if any(not record.get("locked") for record in final): raise RuntimeError(f"Unlocked files remain in folder {folder['id']}")
    return current,len(final)

async def assert_annotation_files(client,title,assignment,attachment_id):
    source=await common.api(client,"GET",f"/files/{attachment_id}"); clone_id=int(assignment.get("annotatable_attachment_id") or 0); clone=await common.api(client,"GET",f"/files/{clone_id}") if clone_id else {}
    if clone and not clone.get("locked"): clone=await common.api(client,"PUT",f"/files/{clone_id}",data={"locked":"true"})
    if not clone_id or source.get("locked") is not True or clone.get("locked") is not True or clone.get("filename")!=source.get("filename") or int(clone.get("size") or -1)!=int(source.get("size") or -2): raise RuntimeError(f"Annotation attachment invariant failed for {title!r}")

async def upsert_practice_assignment(client,title,description,attachment_id):
    assignment=await common.upsert_assignment(client,title,description,["student_annotation","online_upload","online_text_entry"],attachment_id)
    assignment=await common.api(client,"GET",f"/courses/{COURSE_ID}/assignments/{assignment['id']}")
    if assignment.get("published") or float(assignment.get("points_possible") or 0)!=0 or assignment.get("grading_type")!="percent" or assignment.get("omit_from_final_grade") is not True or set(assignment.get("submission_types") or [])!={"student_annotation","online_upload","online_text_entry"}: raise RuntimeError(f"Practice assignment invariant failed for {title!r}")
    await assert_annotation_files(client,title,assignment,attachment_id); return assignment

async def require_formative_assignment(client,found,description,attachment_id):
    assignment=await common.api(client,"PUT",f"/courses/{COURSE_ID}/assignments/{found['id']}",data={
        "assignment[name]":TITLES[5],
        "assignment[description]":description,
        "assignment[published]":"false",
        "assignment[points_possible]":"0",
        "assignment[grading_type]":"percent",
        "assignment[omit_from_final_grade]":"true",
        "assignment[submission_types][]":["student_annotation","online_upload","online_text_entry"],
        "assignment[annotatable_attachment_id]":str(attachment_id),
    })
    assignment=await common.api(client,"GET",f"/courses/{COURSE_ID}/assignments/{assignment['id']}")
    if assignment.get("published") or float(assignment.get("points_possible") or 0)!=0 or assignment.get("grading_type")!="percent" or assignment.get("omit_from_final_grade") is not True or set(assignment.get("submission_types") or [])!={"student_annotation","online_upload","online_text_entry"}: raise RuntimeError("Week 6 formative assignment post-update invariant failed")
    await assert_annotation_files(client,TITLES[5],assignment,attachment_id); return assignment

async def lock_every_file_in_folder(client,folder):
    """Keep older licensed/support files private even when this build no longer links them."""
    records=await common.paged(client,f"/folders/{folder['id']}/files")
    locked=[]
    for record in records:
        if not record.get("locked"):
            record=await common.api(client,"PUT",f"/files/{record['id']}",data={"locked":"true"})
        locked.append(record)
    return locked

