async def upsert_quiz(client):
    qs=await common.paged(client,f"/courses/{COURSE_ID}/quizzes"); matches=[q for q in qs if q.get("title")==TITLES[4]]
    if len(matches)>1: raise RuntimeError(f"Duplicate quizzes named {TITLES[4]!r}: {[entry['id'] for entry in matches]}")
    found=matches[0] if matches else None
    data={"quiz[title]":TITLES[4],"quiz[description]":"<p>Ungraded, unlimited-retry practice on labor, license, and commission labels.</p>","quiz[quiz_type]":"practice_quiz","quiz[published]":"false","quiz[allowed_attempts]":"-1","quiz[show_correct_answers]":"true","quiz[shuffle_answers]":"false"}
    quiz=await common.api(client,"PUT" if found else "POST",f"/courses/{COURSE_ID}/quizzes/{found['id']}" if found else f"/courses/{COURSE_ID}/quizzes",data=data)
    existing=await common.paged(client,f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions")
    desired_names={name for name,*_rest in QUESTIONS}
    for prior_question in existing:
        if prior_question.get("question_name") not in desired_names:
            await common.api(client,"DELETE",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions/{prior_question['id']}")
    existing=[entry for entry in existing if entry.get("question_name") in desired_names]
    unique=[]; seen_names=set()
    for prior_question in existing:
        name=prior_question.get("question_name")
        if name in seen_names:
            await common.api(client,"DELETE",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions/{prior_question['id']}")
        else:
            seen_names.add(name); unique.append(prior_question)
    existing=unique
    for pos,(name,prompt,correct,wrong,yes,no) in enumerate(QUESTIONS,1):
        old=next((q for q in existing if q.get("question_name")==name),None); payload={"question":{"question_name":name,"question_text":prompt,"question_type":"multiple_choice_question","position":pos,"points_possible":1,"correct_comments":yes,"incorrect_comments":no,"answers":[{"answer_text":correct,"answer_weight":100}]+[{"answer_text":x,"answer_weight":0} for x in wrong]}}
        path=f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions/{old['id']}" if old else f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions"; await common.api(client,"PUT" if old else "POST",path,json=payload)
    expected=[name for name,*_rest in QUESTIONS]
    final_questions=await common.paged(client,f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions")
    final_by_name={entry.get("question_name"):entry for entry in final_questions}
    if set(final_by_name)!=set(expected) or len(final_questions)!=len(expected):
        raise RuntimeError(f"Real Estate Quiz mismatch: expected {expected}, found {[entry.get('question_name') for entry in final_questions]}")
    reorder_fields=[]
    for name in expected:
        reorder_fields.extend([("order[][id]",str(final_by_name[name]["id"])),("order[][type]","question")])
    await common.api(client,"POST",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/reorder",content=urlencode(reorder_fields),headers={"Content-Type":"application/x-www-form-urlencoded"})
    final_questions=await common.paged(client,f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions")
    actual=[entry.get("question_name") for entry in final_questions]
    if actual!=expected:
        raise RuntimeError(f"Real Estate Quiz mismatch: expected {expected}, found {actual}")
    final=await common.api(client,"GET",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}")
    if final.get("published") or final.get("quiz_type")!="practice_quiz" or int(final.get("allowed_attempts") or 0)!=-1: raise RuntimeError(f"Practice Quiz invariant failed for {TITLES[4]!r}")
    return final

